#!/usr/bin/env node
// Generates apps/monitor/abis/*.ts from Foundry artifacts in contracts/out.
// Run `cd contracts && forge build` first, then `pnpm --filter @session-firewall/monitor abis`.
// The generated files are committed so the monitor builds without Foundry.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const out = join(here, "..", "..", "..", "contracts", "out");
const abisDir = join(here, "..", "abis");

function artifact(file, name) {
  return JSON.parse(readFileSync(join(out, file, `${name}.json`), "utf8")).abi;
}

function pick(abi, names) {
  const picked = abi.filter((x) => names.includes(x.name));
  for (const n of names) {
    if (!picked.some((x) => x.name === n))
      throw new Error(`missing ${n} in artifact`);
  }
  return picked;
}

function write(file, exportName, source, abi) {
  const body = `// Generated by scripts/gen-abis.mjs from ${source}. Do not edit by hand.\n\nexport const ${exportName} = ${JSON.stringify(abi, null, 2)} as const;\n`;
  writeFileSync(join(abisDir, file), body);
  console.log(`wrote abis/${file} (${abi.length} entries)`);
}

write(
  "FirewallModule.ts",
  "FirewallModuleAbi",
  "contracts/out/FirewallModule.sol/FirewallModule.json",
  artifact("FirewallModule.sol", "FirewallModule"),
);

write(
  "FirewallErrors.ts",
  "FirewallErrorsAbi",
  "contracts/out/FirewallErrors.sol/FirewallErrors.json + ExecutionDecoder.sol errors",
  [
    ...artifact("FirewallErrors.sol", "FirewallErrors"),
    ...artifact("ExecutionDecoder.sol", "ExecutionDecoder").filter(
      (x) => x.type === "error",
    ),
  ],
);

write(
  "EntryPoint.ts",
  "EntryPointAbi",
  "contracts/out/IEntryPoint.sol/IEntryPoint.json (EntryPoint v0.7, events only)",
  pick(artifact("IEntryPoint.sol", "IEntryPoint"), [
    "UserOperationEvent",
    "UserOperationRevertReason",
  ]),
);

// Safe7579 events are not in any interface ModuleKit 0.5.9 compiles, so they are written out here.
// Source: rhinestonewtf/safe7579 src/Safe7579.sol (emergencyUninstallHook) and
// src/core/ExecutionHelper.sol (ExecutionFailed). See docs/decisions.md V10, V11.
write(
  "Safe7579.ts",
  "Safe7579Abi",
  "rhinestonewtf/safe7579 (hand-listed fragments)",
  [
    {
      type: "event",
      name: "EmergencyHookUninstallRequest",
      anonymous: false,
      inputs: [
        {
          name: "hook",
          type: "address",
          indexed: false,
          internalType: "address",
        },
        {
          name: "time",
          type: "uint256",
          indexed: false,
          internalType: "uint256",
        },
      ],
    },
    {
      type: "event",
      name: "EmergencyHookUninstallRequestReset",
      anonymous: false,
      inputs: [
        {
          name: "hook",
          type: "address",
          indexed: false,
          internalType: "address",
        },
        {
          name: "time",
          type: "uint256",
          indexed: false,
          internalType: "uint256",
        },
      ],
    },
    { type: "error", name: "ExecutionFailed", inputs: [] },
  ],
);
